import { requireEvidenceKind, clamp01, stableId, isoOrNull } from '../core/contracts.js';
export function normalizePollutionEvidence(input={}){const kind=requireEvidenceKind(input.evidenceKind);if(!kind||!input.sourceId)return null;return Object.freeze({id:input.id||stableId([input.sourceId,input.externalId,input.observedAt,input.pollutant]),domain:String(input.domain||'UNKNOWN').toUpperCase(),pollutant:input.pollutant||null,evidenceKind:kind,sourceId:String(input.sourceId),observedAt:isoOrNull(input.observedAt),validAt:isoOrNull(input.validAt)||isoOrNull(input.observedAt),lat:Number.isFinite(input.lat)?input.lat:null,lon:Number.isFinite(input.lon)?input.lon:null,confidence:clamp01(input.confidence??1),officialSourceAttribution:input.officialSourceAttribution||null,payload:structuredClone(input.payload||{})});}
export function buildPollutionEvent(signals=[],meta={}){const evidence=signals.map(normalizePollutionEvidence).filter(Boolean);if(!evidence.length)return{state:'UNAVAILABLE',reason:'NO_VALID_EVIDENCE',evidence:[]};const domain=meta.domain||evidence[0].domain;const pollutant=meta.pollutant||evidence.find(x=>x.pollutant)?.pollutant||null;const attributed=evidence.map(x=>x.officialSourceAttribution).filter(Boolean);return{eventId:meta.eventId||stableId([domain,pollutant,meta.startedAt,evidence[0].id]),domain,pollutant,startedAt:isoOrNull(meta.startedAt)||evidence.map(x=>x.observedAt).filter(Boolean).sort()[0]||null,evidence,sourceAttribution:attributed.length?{status:'OFFICIAL_OR_REPORTED',values:[...new Set(attributed)]}:{status:'SOURCE_NOT_ATTRIBUTED',values:[]},truthLegend:[...new Set(evidence.map(x=>x.evidenceKind))]};}
